{
  "evidence": [
    {
      "ref_id": "p006",
      "group_ids": [
        "P1"
      ],
      "quote": "信達生物秉持同工同酬的基本原則，建立了多元的薪酬體系，構成部分包括固定薪酬、可變薪酬和長期股權激勵等。我們每年進行行業薪酬水平與福利體系的調研，確保信達生物員工的收入與待遇始終處於行業領先水平。",
      "kind": "policy",
      "period": "未明确",
      "scope": "全体员工",
      "relevance": "披露了薪酬体系构成及同工同酬原则，虽主要强调竞争力，但‘同工同酬’涉及工资支付的基本公平性保障，且明确了薪酬结构（固定/可变），属于具体的薪酬政策描述。"
    },
    {
      "ref_id": "p007",
      "group_ids": [
        "P2"
      ],
      "quote": "信達生物打造了一套完善的績效管理體系...並通過年度及半年度的績效考核與及時反饋...員工的直屬領導將基於評估結果，與員工展開一對一的深度溝通，提供詳盡且具             有針對性的反饋與改進建議",
      "kind": "mechanism",
      "period": "未明确",
      "scope": "所有员工",
      "relevance": "绩效评估结果直接关联年终奖等可变薪酬（见p006/p007图表），一对一反馈机制构成了员工了解其绩效及对应薪酬依据的查询与沟通渠道。"
    },
    {
      "ref_id": "p005",
      "group_ids": [
        "P4"
      ],
      "quote": "信達生物嚴格遵守《中華人民共和國勞動法》《中華人民   人力資源管理制度，充分保障自身員工、供應商、承包商                                                                   共和國勞動合同法》《中華人民共和國社會保險法》《世   及合作夥伴的用工合規性，實施高標準的人權保護實踐。",
      "kind": "boundary",
      "period": "未明确",
      "scope": "自身员工、供应商、承包商及合作伙伴",
      "relevance": "明确了合规雇佣及人权保护（含劳动权益）的适用对象范围，间接界定了薪酬支付保障政策的覆盖主体。"
    }
  ]
}
